import type { Item } from './undo.ts'

// Every user's notes, by lower-cased name, with who shared them and when they added them.
export type NoteStore = {
  notes: Map<string, Item[]>
  // Display name of each owner who has shared a note, by store key.
  owners: Map<string, string>
  // Times of the adds that went through, per user.
  added: Map<string, number[]>
  // Highest note number ever assigned to a user, so numbers are never reused.
  numbers: Map<string, number>
  nextId: () => string
}

export function createNoteStore(): NoteStore {
  let seq = 0
  const nextId = () => `n${++seq}`
  // Entries are given newest first; numbers are assigned oldest first so the first entry ever added is No. 1.
  const seed = (notes: [string, string][]) =>
    notes.map(([title, createdAt], i) => ({
      id: nextId(),
      title,
      body: '',
      pinned: false,
      createdAt,
      archived: false,
      sharedWith: [] as string[],
      number: notes.length - i,
    }))
  const ada = seed([['Buy milk', '2026-01-15T09:00:00.000Z'], ['Call Bob', '2026-01-14T09:00:00.000Z']])
  const bob = seed([["Bob's secret", '2026-01-10T09:00:00.000Z']])
  return {
    notes: new Map<string, Item[]>([
      ['ada', ada],
      ['bob', bob],
    ]),
    owners: new Map(),
    added: new Map(),
    numbers: new Map([
      ['ada', ada.length],
      ['bob', bob.length],
    ]),
    nextId,
  }
}

// The next note number for a user: one past the highest ever assigned to them, never reused.
export const nextNumber = (store: NoteStore, key: string) => {
  const n = (store.numbers.get(key) ?? 0) + 1
  store.numbers.set(key, n)
  return n
}

// Drops everything kept for a user: their notes (archived and shared ones included), sharing, add history and numbering.
export const purgeUser = (store: NoteStore, key: string) => {
  store.notes.delete(key)
  store.owners.delete(key)
  store.added.delete(key)
  store.numbers.delete(key)
}

